class StableAmountSorter {

    private static final Logger log = Logger.getLogger(StableAmountSorter.class.getName());

    void sort(int[] a) {
        if (a.length < 2) return;
        int[] buffer = new int[a.length];        // reusable temp buffer
        mergeSort(a, buffer, 0, a.length - 1);
    }

    private void mergeSort(int[] a, int[] buffer, int lo, int hi) {
        if (lo >= hi) return;                     // one element → sorted
        int mid = lo + (hi - lo) / 2;             // overflow-safe midpoint
        mergeSort(a, buffer, lo, mid);            // sort left half
        mergeSort(a, buffer, mid + 1, hi);        // sort right half
        merge(a, buffer, lo, mid, hi);            // merge the two sorted halves
    }

    private void merge(int[] a, int[] buffer, int lo, int mid, int hi) {
        for (int i = lo; i <= hi; i++) buffer[i] = a[i];  // snapshot range
        int i = lo, j = mid + 1, k = lo;
        while (i <= mid && j <= hi) {
            // '<=' takes the LEFT element on ties → stable
            if (buffer[i] <= buffer[j]) {
                a[k++] = buffer[i++];
            } else {
                a[k++] = buffer[j++];
            }
        }
        while (i <= mid) a[k++] = buffer[i++];    // drain left remainder
        while (j <= hi) a[k++] = buffer[j++];     // drain right remainder
        log.fine(() -> "  merged range [" + lo + "," + hi + "]");
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
